create index if not exists gateway_transactions_external_idx on public.gateway_transactions (user_id, external_id) where external_id is not null; create index if not exists checkout_sessions_status_time_idx on public.checkout_sessions (user_id,status,created_at desc); create index if not exists sales_funnel_time_idx on public.sales (user_id,funnel_id,created_at desc); create index if not exists sales_checkout_idx on public.sales (user_id,checkout_id) where checkout_id is not null; create index if not exists recovery_events_checkout_time_idx on public.recovery_events (user_id,checkout_id,created_at desc); create index if not exists automation_executions_event_idx on public.automation_executions (user_id,event_id,created_at desc) where event_id is not null;